import{_ as t,o as e,c as r,ag as s}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-11-04（网络安全）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/cybersecurity/science-daily-2026-11-04.md","filePath":"topics/cybersecurity/science-daily-2026-11-04.md"}'),c={name:"topics/cybersecurity/science-daily-2026-11-04.md"};function i(n,o,a,l,d,g){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-11-04-网络安全" tabindex="-1">科学日报 · 2026-11-04（网络安全） <a class="header-anchor" href="#科学日报-·-2026-11-04-网络安全" aria-label="Permalink to &quot;科学日报 · 2026-11-04（网络安全）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-04.md</code> — 第54期 AI 板块</p></blockquote><hr><h2 id="mcp-工具投毒-首个带「真实执行」的跨框架测量-总-asr-22-9-arxiv-2611-03555" tabindex="-1">MCP 工具投毒：首个带「真实执行」的跨框架测量，总 ASR 22.9%（arXiv:2611.03555） <a class="header-anchor" href="#mcp-工具投毒-首个带「真实执行」的跨框架测量-总-asr-22-9-arxiv-2611-03555" aria-label="Permalink to &quot;MCP 工具投毒：首个带「真实执行」的跨框架测量，总 ASR 22.9%（arXiv:2611.03555）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-04.md</code> ｜ arXiv: 2611.03555 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>场景：<strong>模型上下文协议（MCP）</strong> 让智能体框架连接外部工具提供方，却把<strong>攻击者可控的内容（工具描述、schema 字段、响应数据）</strong> 未经校验地送进<strong>模型上下文</strong>——攻击面由此打开。</li><li>难点：此前基准只测<strong>模型是否服从</strong>被投毒的指令，<strong>没有确认真实执行</strong>（可能只是「口头答应」而非真调用工具/真外泄），于是对真实风险的刻画失真。</li><li>方法： <ul><li>给出一个 <strong>25 类根因分类法</strong>，统一既有分类；</li><li>开源工具 <strong>mcpvenom</strong> 驱动 <strong>12 框架 × 18 模型 × 45 攻击场景 = 9,720 格</strong> 的<strong>易感性矩阵</strong>；</li><li>用<strong>双 oracle（含 canary HTTP 回执）</strong> 确认是否<strong>真实外泄</strong>。</li></ul></li><li>结果（实测）： <ul><li>总体<strong>攻击成功率 ASR 22.9%</strong>（2,113 个脆弱格）；其中 <strong>64.9% 触发了攻击者工具调用、23.0% 联系了攻击者端点、12.1% 确证外泄了秘密</strong>；</li><li>抗性主要在<strong>模型层</strong>：<strong>9 个核心框架聚集在 23–26%</strong>（χ²=3.30, p=0.91），且<strong>代码级审计发现 12 个框架无一实现有意防御</strong>；</li><li>正则描述扫描仅拦下 45 场景中的 20 个（<strong>误报率 7.2%</strong>）→ <strong>单靠元数据扫描只是部分控制</strong>；<strong>模型 ASR 跨度 0.4%–49.7%</strong>（Claude Opus 4.8 在 530 格中 8 格脆弱，同时发出 223 次显式拒绝）。</li></ul></li><li>洞察（对本库 <code>cybersecurity</code> × <code>ai-system-architecture</code>）： <ol><li><strong>「口头拒绝 ≠ 真实执行」——必须用可验证 oracle 收口</strong>——声称「模型会拒绝」不等于「没有攻击者工具调用/外泄」；判据：<strong>评估智能体安全时，把『能否用 canary/回执等端到端证据确认后果』当作及格线</strong>（呼应母题「<strong>外部信号 &gt; 自评分</strong>」与「<strong>否证性判据优于肯定性判据</strong>」）。</li><li><strong>「防御在模型层、框架层缺席」——责任错配</strong>——攻击面在<strong>协议/框架</strong>层（无校验地搬运不可信内容），抗性却主要由<strong>模型</strong>扛；判据：<strong>做智能体安全时，先问『这类风险该在哪一层被结构性消除』，而非指望下游模型拒绝</strong>（同族：本库 10-22 Proof-Carrying Contracts 的「把保证放回工具契约层」）。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/cybersecurity/index.md</code> ｜ <code>topics/ai-system-architecture/index.md</code> ｜ 第54期 AI 板块</p></blockquote><p>关键词：科学日报第54期、MCP工具投毒、Model Context Protocol、跨框架测量、真实工具执行、25类根因分类法、mcpvenom、9720格易感性矩阵、12框架18模型45场景、双oracle canary HTTP回执、总ASR22.9%、确证外泄12.1%、抗性在模型层、九核心框架23-26%、无框架有意防御、正则描述扫描20/45误报7.2%、模型ASR0.4%-49.7%、口头拒绝不等于真实执行、端到端证据收口、防御责任在模型层框架层缺席、外部信号大于自评分、否证性判据优于肯定性判据、工具契约层保证</p><p>关联：<code>topics/cybersecurity/index.md</code>、<code>topics/cybersecurity/science-daily-2026-10-13.md</code>、<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-system-architecture/science-daily-2026-11-04-ai.md</code>、<code>topics/ai-system-architecture/science-daily-2026-11-03-ai.md</code>、<code>ScienceDaily/daily/2026-11-04.md</code></p>',10)])])}const y=t(c,[["render",i]]);export{u as __pageData,y as default};
